// Return the set union of the int arrays `a` and `b`: every distinct value
// that appears in either array, with duplicates removed.
//
// Written with an explicit seen-mapping rather than the array `|` set
// operator, because `|` (union_array()) drops the elements of the *second*
// operand when the first operand is empty -- ({ 1 } | ({ })) is ({ 1 }),
// but ({ 1 } | ({ 1 })) is empty, i.e. `a | b` is really `a - b` plus
// nothing.  The mapping below also keeps the driver from sorting the
// result: values come out in first-seen order, `a` before `b`.

public int *unify_sets(int *a, int *b) {
    mapping seen = ([]);
    int *result = ({});
    int val;

    foreach (val in a) {
        if (!seen[val]) {
            seen[val] = 1;
            result += ({ val });
        }
    }

    foreach (val in b) {
        if (!seen[val]) {
            seen[val] = 1;
            result += ({ val });
        }
    }

    return result;
}

