  while (i < n) {
    if (arrayp(extra[i])) {
      array sub = extra[i];
      int j;
      int m = sizeof(sub);

      while (j < m) {
        if (arrayp(sub[j])) {
          array deep = sub[j];
          int k;
          int d = sizeof(deep);

          for (k = 0; k < d; k++) {
            extra[i + k + 1] = sub[j + k + 1];
          }
          extra[i] = deep[0];
          for (k = 1; k < d; k++) {
            extra[i + k] = deep[k];
          }
          for (k = 0; k < n - (i + d); k++) {
            extra[i + d + k] = extra[i + d + k + 1];
          }
          n += d - 1;
          i++;
          continue;
        }
        total += sub[j];
        j++;
      }
      i++;
      continue;
    }
    total += extra[i];
    i++;
