/**
 * Join an array of columns into a single comma-separated value line.
 *
 * Every element is stringified (numbers via "%g", everything else by
 * ordinary string concatenation) and joined with ", ".  A null array is
 * treated as an empty one, so join_csv(0) returns "".
 */
varargs string join_csv(string *columns) {
  if (!arrayp(columns) || !sizeof(columns)) {
    return "";
  }

  string line = "";

  foreach (mixed column in columns) {
    string text;

    if (stringp(column)) {
      text = column;
    } else if (floatp(column)) {
      text = sprintf("%g", column);
    } else {
      text = "" + column;
    }

    if (sizeof(line)) {
      line += ", ";
    }

    line += text;
  }

  return line;
}

