// resolve_value(mixed val_or_func, int arg)
//
// Transparently accepts either a plain value or a dynamic callback and
// always returns the *value*.  A function pointer (local function, efun,
// simul efun, call_other, functional, ...) is run through evaluate() with
// `arg` as its argument; anything else is handed back untouched.
//
// This lets a mudlib setter/query pair store either a constant or a thunk:
//     set_hp( 10 );            // constant
//     set_hp( (: query_max_hp :) );  // recomputed on every query
//     query_hp() -> resolve_value(hp, arg);

public varargs mixed resolve_value(mixed val_or_func, int arg) {
  if (functionp(val_or_func)) {
    return evaluate(val_or_func, arg);
  }

  return val_or_func;
}

